<div class="card shadow-sm mb-4"><div class="card-body"><dl class="row mb-3"><dt class="col-sm-3">Status</dt><dd class="col-sm-9"><strong><?=html_escape($version->version_status)?></strong></dd><dt class="col-sm-3">Source cutoff</dt><dd class="col-sm-9"><?=html_escape(date('d-M-Y h:i A',strtotime($version->source_cutoff_at)))?></dd><dt class="col-sm-3">Manifest SHA-256</dt><dd class="col-sm-9"><code><?=html_escape($version->manifest_sha256??'—')?></code></dd><dt class="col-sm-3">Artifact</dt><dd class="col-sm-9"><?=html_escape($version->artifact_file_name??'Not exported')?><?php if($version->artifact_sha256):?><br><code><?=html_escape($version->artifact_sha256)?></code><?php endif;?></dd></dl><div class="d-flex gap-2"><?php if($can_train&&$version->version_status==='DRAFT'):?><?=form_open('ml-governance/versions/'.$version->dataset_version_id.'/freeze')?><button class="btn btn-warning" type="submit">Freeze and Queue Export</button><?=form_close()?><?php endif;?><?php if($can_review&&$version->version_status==='FROZEN'):?><?=form_open('ml-governance/versions/'.$version->dataset_version_id.'/approve')?><button class="btn btn-success" type="submit" <?=$version->artifact_sha256?'':'disabled'?>>Approve Exported Dataset</button><?=form_close()?><?php endif;?></div></div></div>
<div class="alert alert-info">Records are grouped by workbook/import batch, BOQ item, or stable cost item so future train/test splits can prevent source leakage. Only approved labels are exported.</div>
<div class="card shadow-sm mb-4"><div class="card-header"><h2 class="card-title mb-0">Snapshot Records</h2></div><div class="card-body"><?php if((int)$counts->total>500):?><div class="alert alert-warning">Showing the first 500 records. Counts and export include the complete version.</div><?php endif;?><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Source</th><th>Group</th><th>Payload / Label</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($records as$r):?><tr><td><?=html_escape($r->source_identity)?><br><small><?=html_escape($r->record_type)?></small></td><td><?=html_escape($r->split_group_key)?></td><td><details><summary>Inspect immutable JSON</summary><div class="small mt-2"><strong>Payload</strong><pre class="text-wrap"><?=html_escape(json_encode(json_decode($r->payload_json,TRUE),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?></pre><strong>Label</strong><pre class="text-wrap"><?=html_escape(json_encode(json_decode($r->label_json,TRUE),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?></pre><code><?=html_escape($r->record_sha256)?></code></div></details></td><td><?=html_escape($r->label_status)?></td><td><?php if($can_review&&$version->version_status==='DRAFT'):?><?=form_open('ml-governance/versions/'.$version->dataset_version_id.'/records/'.$r->dataset_record_id.'/review')?><select class="form-select form-select-sm mb-2" name="label_status" required><option value="APPROVED">Approve</option><option value="REJECTED">Reject</option><option value="PENDING">Reopen</option></select><input class="form-control form-control-sm mb-2" name="comments" maxlength="1000" placeholder="Review comments"><button class="btn btn-outline-primary btn-sm" type="submit">Record Review</button><?=form_close()?><?php else:?><?=html_escape($r->reviewed_by_name??'—')?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$records):?><p class="text-body-secondary mb-0">No eligible source records were available at this version's cutoff. An empty version cannot be frozen.</p><?php endif;?></div></div>
<div class="card shadow-sm"><div class="card-header"><h2 class="card-title mb-0">Append-Only Label Feedback</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Date</th><th>Record</th><th>Event</th><th>Change</th><th>Actor</th><th>Comments</th></tr></thead><tbody><?php foreach($feedback as$f):?><tr><td><?=html_escape(date('d-M-Y h:i A',strtotime($f->feedback_at)))?></td><td>#<?=(int)$f->dataset_record_id?></td><td><?=html_escape($f->feedback_event)?></td><td><?=html_escape($f->previous_label_status.' → '.$f->new_label_status)?></td><td><?=html_escape($f->feedback_by_name??'—')?></td><td><?=html_escape($f->comments??'—')?></td></tr><?php endforeach;?></tbody></table></div></div></div>
